def canonical_tomac_symbol(symbol: str) -> str:
    root = normalize_futures_root(symbol)
    return CONTRACT_ROOT_ALIASES.get(root, root)


def canonical_tomac_symbol_sequence(symbols: list[str]) -> tuple[list[str], list[dict[str, str]]]:
    canonical_symbols: list[str] = []
    aliases: list[dict[str, str]] = []
    seen: set[str] = set()
    for raw_symbol in symbols:
        requested = str(raw_symbol).upper().strip()
        if not requested:
            continue
        canonical = canonical_tomac_symbol(requested)
        if requested != canonical:
            aliases.append({"requested": requested, "canonical": canonical})
        if canonical not in seen:
            canonical_symbols.append(canonical)
            seen.add(canonical)
    return canonical_symbols, aliases


def has_pyarrow() -> bool:
    try:
        import pyarrow  # noqa: F401
    except Exception:
        return False
    return True


def pyarrow_runtime_reexec_argv(
    *,
    current_executable: Path,
    preferred_python: Path,
    argv: list[str],
    pyarrow_available: bool,
    script_path: Path,
) -> list[str] | None:
    if pyarrow_available or not preferred_python.exists():
        return None
    if current_executable.resolve() == preferred_python.resolve():
        return None
    return [str(preferred_python), str(script_path), *argv[1:]]


def ensure_pyarrow_runtime() -> None:
    reexec_argv = pyarrow_runtime_reexec_argv(
        current_executable=Path(sys.executable),
        preferred_python=AQ_PY,
        argv=sys.argv,
        pyarrow_available=has_pyarrow(),
        script_path=Path(__file__).resolve(),
    )
    if reexec_argv is not None:
        os.execv(reexec_argv[0], reexec_argv)


@dataclass(frozen=True)
class TomacSource:
    symbol: str
    source_csv: Path
    schema: str = "databento_parent_ohlcv_1m"
    archive_zip: Path | None = None
    archive_member: str | None = None


@dataclass(frozen=True)
class CandidateSpec:
    key: str
    class_prefix: str
    main_regime: str
    sub_regime: str
    profit_factor: str
    direction: str
    roi: float
    stoploss: float
    trailing_positive: float
    trailing_offset: float
    child_profit_factor: str | None = None
    extra_profit_factors: tuple[str, ...] = ()
    factor_id_by_timeframe: tuple[tuple[str, str], ...] = ()
    allowed_symbols: tuple[str, ...] = ()
    allowed_timeframes: tuple[str, ...] = ()

    @property
    def branch_path(self) -> str:
        segments = [self.main_regime, self.sub_regime, self.profit_factor]
        if self.child_profit_factor:
            segments.append(self.child_profit_factor)
        segments.extend(self.extra_profit_factors)
        return " -> ".join(segments)

    def factor_id(self, timeframe: str) -> str:
        for item_timeframe, factor_id in self.factor_id_by_timeframe:
            if item_timeframe == timeframe:
                return factor_id
        return f"tomac_idxfut_clean_{self.key}_{timeframe}_v1"

    def branch_path_with_factor(self, timeframe: str) -> str:
        return f"{self.branch_path} -> {self.factor_id(timeframe)}"

    def supports(self, *, symbol: str, timeframe: str) -> bool:
        if self.allowed_symbols and symbol.upper() not in self.allowed_symbols:
            return False
        if self.allowed_timeframes and timeframe not in self.allowed_timeframes:
            return False
        return True


@dataclass(frozen=True)
class GeneratedStrategySpec:
    class_name: str
    symbol: str
    timeframe: str
    factor_id: str
    branch_path: str
    family: str
    direction: str


